function agg(rows){
  const a = {s:0,ca:0,ms:0,ld:0,in:0,bk:0,bv:0,o:0,sl:0,po:0,so:0};
  const od = {};
  for (const r of rows) {
    for (const k in a) if (k !== "o" && k !== "po" && k !== "so") a[k] += +r[k] || 0;
    if (r.o) { const x = od[r.d] = od[r.d] || { so:0, po:0 }; if (r.p === "_store") x.so += +r.o; else if (r.p !== "_bk") x.po += +r.o; }
